{
  "correction_rules": [
    "Reduce forecast bias when sentiment is negative (sentiment < 0) — model tends to overestimate prices.",
    "Adjust downward for long-term forecasts (30d) when recent prices show strong mean reversion or downward momentum.",
    "Apply a lag correction: if true outcome is significantly lower than forecast, reduce next period’s forecast by 5–10% to account for delayed price adjustment.",
    "Cap forecast spikes above 75% of recent 15-day high — avoid over-optimistic overshoots.",
    "When sentiment is positive (sentiment > 0), slightly increase forecast volatility to reflect bullish momentum, but cap at 10% above recent mean.",
    "For forecasts with high error variance, apply a smoothing filter: average last 3 true outcomes before adjusting next forecast."
  ]
}
